<script setup lang="ts">
import {localize} from './localization';

import {computed,ref,watch} from 'vue';
import {useSession} from './store';
import WorkspaceSplit from './WorkspaceSplit.vue';
import ReferencesPanel from './ReferencesPanel.vue';
import MarkingLibrary from './MarkingLibrary.vue';


const props=defineProps<{language:'zh'|'en';targetId?:string;selection?:{markingId:string;pieceId:string}}>(),emit=defineEmits<{model:[];unwrap:[];select:[id:string]}>(),store=useSession(),zh=computed(()=>props.language==='zh');
const layout=ref<'separate'|'front-left'|'front-right'>('front-right'),height=ref(1800),clusters=ref(6),exclude=ref(true),mode=ref<'simple'|'precise'>('simple'),subject=ref<'character'|'head'|'paw'|'foot'>('character');
const extracting=ref(false),selectedSource=ref<string>();
const selectedTarget=computed(()=>selectedSource.value??props.targetId);
watch(()=>props.targetId,()=>{selectedSource.value=undefined;});
function selectSource(id:string){selectedSource.value=id;emit('select',id);}
function dismissDetail(event:PointerEvent){const target=event.target as Element;if(target.closest('.marking-library,button,input,select,textarea,label,summary,a,[role=toolbar],.mask-controls,.tool-options,.zoom-toolbar,.pen-node,.pen-handle,[data-source-region-id]'))return;selectSource('');}
async function cancelExtraction(){const p=store.data.project;if(p)await window.fpcad.cancelSurface(p.id,p.revision);}
const valid=computed(()=>Number.isFinite(height.value)&&height.value>=1&&height.value<=10000&&Number.isInteger(clusters.value)&&clusters.value>=2&&clusters.value<=16);
watch(()=>store.data.project?.id,()=>{const r=store.data.project?.references?.[0];mode.value='simple';subject.value='character';height.value=1800;if(r?.illustration?.subject)subject.value=r.illustration.subject;if(r?.calibration)height.value=r.calibration.distanceMm;},{immediate:true});
async function importSingle(){const p=store.data.project;if(p&&await store.run(()=>window.fpcad.importReference(p.id,p.revision,'front')))selectedSource.value=store.data.project?.references?.find(r=>r.view==='front')?.id??'';}
async function upload(){const p=store.data.project;if(p&&valid.value){extracting.value=true;try{await store.run(()=>window.fpcad.autoReference(p.id,p.revision,layout.value,height.value,clusters.value,exclude.value,mode.value,subject.value));}finally{extracting.value=false;}}}
async function split(){const p=store.data.project;if(p&&valid.value){extracting.value=true;try{await store.run(()=>window.fpcad.splitAllReferences(p.id,p.revision,height.value,clusters.value,exclude.value,mode.value,subject.value));}finally{extracting.value=false;}}}
</script>
<template><WorkspaceSplit class="markings-page" storage-key="extraction-panels" @pointerdown.capture="dismissDetail" :language="language" :label="zh?'花纹图片与分类预览宽度':localize('Reference and library preview widths')" :initial=".72"><template #first><div class="reference-workspace"><section class="auto-reference"><span class="eyebrow">01 / {{zh?'正背视图 → 部位花纹':localize('FRONT / BACK → PART MARKINGS')}}</span><h2>{{zh?'提取角色花纹':localize('Extract character markings')}}</h2><p>{{zh?'沿原图的连续颜色区域提取，合并相近阴影；部位标签不会切开色块。正背视图共同预览，遮挡区域通过对应色区生成补全候选。':localize('Merge pigment shading, remove stroke fragments, smooth outlines and suggest editable part categories. Both views describe colors and transitions; only existing model parts receive markings.')}}</p><div class="auto-options"><label>{{zh?'图片布局':localize('Image layout')}}<select v-model="layout" aria-label="双视图布局"><option value="front-right">{{zh?'合图：左背面 / 右正面':localize('Combined: back left / front right')}}</option><option value="front-left">{{zh?'合图：左正面 / 右背面':localize('Combined: front left / back right')}}</option><option value="separate">{{zh?'两张独立正背图':localize('Separate front/back images')}}</option></select><small>{{zh?'按角色朝向选择。优先找两个人物间的空隙。':localize('Choose the actual orientation before import.')}}</small></label><label >{{zh?'参考图内容':localize('Reference subject')}}<select v-model="subject" aria-label="参考图内容"><option value="character">{{zh?'完整角色':localize('Whole character')}}</option><option value="head">{{zh?'仅头部':localize('Head only')}}</option><option value="paw">{{zh?'仅手爪':localize('Paw only')}}</option><option value="foot">{{zh?'仅脚':localize('Foot only')}}</option></select></label><label>{{zh?(mode==='simple'?'角色 / 部件实际高度 mm':'图像全高对应 mm'):'Real height in mm'}}<input v-model.number="height" aria-label="参考高度 mm" type="number" min="1" max="10000"><small>{{zh?'1800 mm = 180 cm。精确制作可在标定工具中校正。':localize('1800 mm = 180 cm. Use landmark calibration for precise work.')}}</small></label><template v-if="false"><label>{{zh?'颜色数':localize('Colors')}}<input v-model.number="clusters" type="number" min="2" max="16"><small>{{zh?'颜色过多会把阴影分成碎片。':localize('Too many colors fragment shading.')}}</small></label><label class="check-label"><input v-model="exclude" type="checkbox">{{zh?'移除主背景连通区域':localize('Remove dominant border background')}}</label></template></div><p v-if="!valid" class="error" role="alert">{{zh?'高度须为 1–10000 mm，颜色数须为 2–16 的整数。':localize('Height must be 1–10000 mm and colors an integer from 2 to 16.')}}</p><div class="reference-actions"><button :disabled="store.busy" @click="importSingle">{{zh?'导入单张原图':localize('Import single image')}}</button><button v-if="extracting" @click="cancelExtraction">{{zh?'取消后台拆分':localize('Cancel extraction')}}</button><button class="primary" :disabled="store.busy||!valid" @click="upload">{{zh?'上传双视图并自动拆分':localize('Upload dual views and split')}}</button><button :disabled="store.busy||!valid||store.data.project?.references?.length!==2" @click="split()">{{zh?'按当前标定重新拆分':localize('Split with current calibration')}}</button><button :disabled="!store.data.project?.patternLibrary?.length" @click="emit('model')">{{zh?'下一步：模型管理 →':localize('Next: model management →')}}</button></div><small>{{zh?'部位识别是可修正的候选：姿势特别、遮挡或局部图请检查分类。重新拆分会替换花纹库和相关贴附；已锁定来源会阻止替换。':localize('Part suggestions are editable; review unusual poses and occlusion. Resplitting replaces sources and related placements. Locked sources prevent replacement.')}}</small></section><ReferencesPanel :target-id="selectedTarget" library :language="language" :selection="selection" @unwrap="emit('unwrap')" @select="selectSource"/></div></template><template #second><MarkingLibrary :target-id="selectedTarget" :language="language" @select="selectSource"/></template></WorkspaceSplit></template>
<style scoped>.markings-page{height:100%;width:100%;min-height:0}.reference-workspace{height:100%;overflow:auto;background:var(--panel-soft)}.auto-reference{padding:25px 30px;border-bottom:1px solid var(--border)}h2{font-size:23px;margin:8px 0}p,small{color:var(--text-muted);line-height:1.8}.auto-options{display:grid;grid-template-columns:2fr 1fr 1fr;gap:14px;margin:20px 0}.auto-options label{font-size:12px;min-width:0}.auto-options small{display:block;margin-top:5px;font-size:11px}.auto-options .check-label{grid-column:1/-1}.reference-actions{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.mode-switch{display:flex;gap:8px}.mode-switch .active{background:var(--selected);border-color:var(--studio-orange);color:var(--ink)}.manual-reference{padding:18px}.manual-reference summary{cursor:pointer;font-size:14px}.reference-workspace :deep(.reference-view){height:400px}.reference-workspace :deep(.reference-controls){margin-top:15px}@media(max-width:1100px){.auto-reference{padding:18px}.auto-options{grid-template-columns:1fr 1fr}.auto-options label:first-child{grid-column:1/-1}}</style>

